import importlib.util, pathlib, json, torch, time
ROOT=pathlib.Path(__file__).resolve().parent
torch.backends.cuda.matmul.allow_tf32=False
torch.backends.cudnn.allow_tf32=False
torch.set_grad_enabled(False)

def load(task):
    path=next((ROOT/'KernelBench/KernelBench/level2').glob(str(task)+'_*.py'))
    spec=importlib.util.spec_from_file_location('task'+str(task),path)
    mod=importlib.util.module_from_spec(spec);spec.loader.exec_module(mod)
    return mod

def summarize(a,b):
    d=(a-b).abs(); limit=1e-4+1e-4*a.abs()
    return {'pass':bool((d<=limit).all()),'max_abs':d.max().item(), 'bad':int((d>limit).sum()),'max_budget_ratio':(d/limit).max().item(), 'min_abs_ref':a.abs().min().item()}

if __name__=='__main__':
    results=[]
    for task in [14,51]:
        mod=load(task)
        for seed in range(5):
            torch.manual_seed(seed)
            model=mod.Model(*mod.get_init_inputs()).cuda().eval()
            x=mod.get_inputs()[0].cuda()
            ref=model(x)
            start=time.perf_counter()
            if task==14:
                out=(x@model.weight.sum(0)).unsqueeze(1)*(model.scaling_factor/2)
                out64=(x.double()@model.weight.double().sum(0)).unsqueeze(1)*(model.scaling_factor/2)
            else:
                lin=model.gemm
                v=lin.weight.mean(0)
                c=lin.bias.mean()-model.subtract.mean()
                out=torch.nn.functional.gelu((x@v+c).unsqueeze(1))+x
                v64=lin.weight.double().mean(0)
                c64=lin.bias.double().mean()-model.subtract.double().mean()
                out64=torch.nn.functional.gelu((x.double()@v64+c64).float().unsqueeze(1))+x
            torch.cuda.synchronize()
            r={'task':task,'seed':seed,'fp32':summarize(ref,out),'fp64':summarize(ref,out64.float())}
            results.append(r);print(json.dumps(r),flush=True)
            del model,x,ref,out,out64
    (ROOT/'scout.json').write_text(json.dumps(results,indent=2))

```


## Source: factored51.py

```python
"""Inference-only CUDA implementation of KernelBench L2/51, no value caching.

Algebra: GELU(mean(X W^T + b - s)) + X
        = GELU(X mean_rows(W) + mean(b-s)) + X in real arithmetic.
FP32 reassociation requires validation against the reference; not bit identical.
"""
import pathlib
import cupy as cp
import numpy as np
import torch

SOURCE = r'''
extern "C" __global__ void partial_weights(const float* w, float* p, int H, int K) {
    __shared__ float buf[8][32];
    int k=blockIdx.x*32+threadIdx.x;
    int start=blockIdx.y*256;
    float a=0.f;
    if (k<K) for(int r=start+threadIdx.y;r<min(start+256,H);r+=8) a+=w[r*K+k];
    buf[threadIdx.y][threadIdx.x]=a;
    __syncthreads();
    if(threadIdx.y==0 && k<K) {
        float z=0.f;
        for(int j=0;j<8;++j) z+=buf[j][threadIdx.x];
        p[blockIdx.y*K+k]=z;
    }
}
extern "C" __global__ void finish_weights(const float* p, const float* b, const float* s,
                                         float* v, int H, int K, int P) {
    if(blockIdx.x==(K+255)/256) {
        __shared__ float buf[256];
        float z=0.f;
        for(int j=threadIdx.x;j<H;j+=256) z+=b[j]-s[j];
        buf[threadIdx.x]=z; __syncthreads();
        for(int t=128;t;t>>=1) {
            if(threadIdx.x<t) buf[threadIdx.x]+=buf[threadIdx.x+t];
            __syncthreads();
        }
        if(threadIdx.x==0) v[K]=buf[0]/H;
    } else {
        int k=blockIdx.x*256+threadIdx.x;
        if(k<K) {
            float z=0.f;
            for(int j=0;j<P;++j) z+=p[j*K+k];
            v[k]=z/H;
        }
    }
}
extern "C" __global__ void dot_gelu(const float* x, const float* v, float* z, int K) {
    __shared__ float buf[256];
    float a=0.f;
    for(int k=threadIdx.x;k<K;k+=256) a=fmaf(x[blockIdx.x*K+k],v[k],a);
    buf[threadIdx.x]=a; __syncthreads();
    for(int t=128;t;t>>=1) {
        if(threadIdx.x<t) buf[threadIdx.x]+=buf[threadIdx.x+t];
        __syncthreads();
    }
    if(threadIdx.x==0) {
        float u=buf[0]+v[K];
        z[blockIdx.x]=0.5f*u*(1.f+erff(u*0.7071067811865475244f));
    }
}
extern "C" __global__ void residual(const float* x, const float* z, float* y, int N, int K) {
    int i=blockIdx.x*256+threadIdx.x;
    if(i<N) y[i]=x[i]+z[i/K];
}
'''
MODULE = cp.RawModule(code=SOURCE, options=('--std=c++11',))
KERNELS = {n:MODULE.get_function(n) for n in ('partial_weights','finish_weights','dot_gelu','residual')}

def view(tensor):
    # Raw non-owning view: launch arguments keep Torch tensors alive; same stream.
    mem=cp.cuda.UnownedMemory(tensor.data_ptr(),tensor.numel()*tensor.element_size(),tensor)
    return cp.ndarray(tuple(tensor.shape),dtype=cp.float32,memptr=cp.cuda.MemoryPointer(mem,0))

def forward(x,w,b,s):
    if not all(t.is_cuda and t.dtype==torch.float32 and t.is_contiguous() for t in (x,w,b,s)):
        raise ValueError('contiguous CUDA FP32 tensors required')
    B,K=x.shape; H=w.shape[0]; P=(H+255)//256
    if w.shape[1]!=K or b.shape!=(H,) or s.shape!=(H,):
        raise ValueError('incompatible shapes')
    p=torch.empty((P,K),device=x.device);v=torch.empty((K+1,),device=x.device)
    z=torch.empty((B,),device=x.device);y=torch.empty_like(x)
    stream=torch.cuda.current_stream(x.device)
    with cp.cuda.Device(x.device.index), cp.cuda.ExternalStream(stream.cuda_stream):
        a=[view(t) for t in (x,w,b,s,p,v,z,y)]
        xx,ww,bb,ss,pp,vv,zz,yy=a
        KERNELS['partial_weights'](((K+31)//32,P),(32,8),(ww,pp,np.int32(H),np.int32(K)))
        KERNELS['finish_weights'](((K+255)//256+1,),(256,),(pp,bb,ss,vv,np.int32(H),np.int32(K),np.int32(P)))
        KERNELS['dot_gelu']((B,),(256,),(xx,vv,zz,np.int32(K)))
        KERNELS['residual'](((B*K+255)//256,),(256,),(xx,zz,yy,np.int32(B*K),np.int32(K)))
    return y

def torch_factored(x,w,b,s):
    v=w.mean(0)
    c=b.mean()-s.mean()
    return torch.nn.functional.gelu((x@v+c).unsqueeze(1))+x

```


## Source: experiment51.py

```python
import argparse, collections, gc, json, pathlib, random, statistics, subprocess, time
import torch
from scout import load, summarize
ROOT=pathlib.Path(__file__).resolve().parent
torch.set_grad_enabled(False)
torch.backends.cuda.matmul.allow_tf32=False
torch.backends.cudnn.allow_tf32=False

def stat(a):
    a=sorted(a)
    return {'median_ms':statistics.median(a),'q25_ms':a[len(a)//4], 'q75_ms':a[3*len(a)//4], 'min_ms':min(a),'max_ms':max(a),'samples_ms':a}

def measure(functions, rounds=25, repeats=5, graph=False):
    fns=functions.copy();keep=[]
    for name,fn in list(fns.items()):
        for _ in range(8):fn()
        torch.cuda.synchronize()
        if graph:
            g=torch.cuda.CUDAGraph()
            with torch.cuda.graph(g): out=fn()
            keep.append((g,out)); fns[name]=g.replay
    values=collections.defaultdict(list)
    rng=random.Random(193)
    for _ in range(rounds):
        order=list(fns);rng.shuffle(order)
        for name in order:
            torch.cuda.synchronize()
            start=torch.cuda.Event(enable_timing=True);end=torch.cuda.Event(enable_timing=True)
            start.record()
            for _ in range(repeats): fns[name]()
            end.record();end.synchronize()
            values[name].append(start.elapsed_time(end)/repeats)
    return {k:stat(v) for k,v in values.items()}

def main():
    parser=argparse.ArgumentParser();parser.add_argument('--seeds',type=int,default=5);parser.add_argument('--timing-only',action='store_true');args=parser.parse_args()
    import_start=time.perf_counter()
    import factored51 as fast
    module_import_seconds=time.perf_counter()-import_start
    result={'commit':subprocess.check_output(['git','-C',str(ROOT/'KernelBench'),'rev-parse','HEAD'],text=True).strip(),
            'gpu':torch.cuda.get_device_name(),'torch':torch.__version__,'cuda_runtime':torch.version.cuda,
            'tf32':False,'tol':{'atol':1e-4,'rtol':1e-4},'correctness':[], 'module_import_wall_seconds':module_import_seconds,
            'timing_method':'25 randomized rounds, 5 repetitions per event pair; 8 warmups; current CUDA stream; inference only; includes fresh weight reduction each invocation'}
    mod=load(51)
    if args.timing_only:
        result['correctness']=json.loads((ROOT/'results51.json').read_text())['correctness']
    for seed in range(0 if args.timing_only else args.seeds):
        torch.manual_seed(seed);m=mod.Model(*mod.get_init_inputs()).cuda().eval()
        x=mod.get_inputs()[0].cuda();w=m.gemm.weight;b=m.gemm.bias;s=m.subtract
        for dist in ['official_uniform','normal','centered_uniform','scaled_100']:
            if dist=='normal':x=torch.randn_like(x)
            elif dist=='centered_uniform':x=torch.rand_like(x)-.5
            elif dist=='scaled_100':x=torch.rand_like(x)*100
            ref=m(x)
            for name,fn in [('torch_factored',fast.torch_factored),('cuda_factored',fast.forward)]:
                t0=time.perf_counter();out=fn(x,w,b,s);torch.cuda.synchronize()
                r={'seed':seed,'distribution':dist,'method':name,**summarize(ref,out)}
                if seed==0 and dist=='official_uniform':r['first_invocation_wall_seconds']=time.perf_counter()-t0
                result['correctness'].append(r);print(json.dumps(r),flush=True)
                del out
            del ref
        del m,x,w,b,s
        gc.collect();torch.cuda.empty_cache()
    torch.manual_seed(42);m=mod.Model(*mod.get_init_inputs()).cuda().eval();x=mod.get_inputs()[0].cuda()
    w=m.gemm.weight;b=m.gemm.bias;s=m.subtract
    ref=m(x)
    result['timing_input_correctness']={name:summarize(ref,fn(x,w,b,s)) for name,fn in [('torch_factored',fast.torch_factored),('cuda_factored',fast.forward)]}
    if not all(r['pass'] for r in result['timing_input_correctness'].values()):
        raise RuntimeError('timing input correctness failed')
    del ref
    fns={'eager_reference':lambda:m(x),'torch_factored':lambda:fast.torch_factored(x,w,b,s),'cuda_factored':lambda:fast.forward(x,w,b,s)}
    try:
        ts=torch.jit.freeze(torch.jit.trace(m,x))
        result['torchscript_correctness']=summarize(m(x),ts(x));fns['torchscript_reference']=lambda:ts(x)
    except Exception as exc: result['torchscript_error']=str(exc)
    for mode in ['events','graph']:
        try:
            result[mode]=measure(fns,graph=(mode=='graph'))
            print(mode,json.dumps(result[mode]),flush=True)
        except Exception as exc:
            result[mode+'_error']=repr(exc);print(mode,repr(exc),flush=True)
    # TF32 is an extra alternative baseline, checked against the strict FP32 reference.
    ref=m(x)
    torch.backends.cuda.matmul.allow_tf32=True
    result['tf32_reference_correctness']=summarize(ref,m(x))
    result['tf32_events']=measure({'tf32_reference':lambda:m(x),'cuda_factored':lambda:fast.forward(x,w,b,s)})
    torch.backends.cuda.matmul.allow_tf32=False
    (ROOT/'results51.json').write_text(json.dumps(result,indent=2))

if __name__=='__main__':main()

```


