import gc,json,time,torch
from scout import ROOT,load,summarize
from experiment51 import measure
import factored51 as fast
torch.set_grad_enabled(False)
torch.backends.cuda.matmul.allow_tf32=False

def main():
    mod=load(51);results={'shape_transfer':[],'controls':[]}
    for B,K,H in [(128,1024,512),(17,257,769),(256,2048,4096)]:
        torch.manual_seed(37);m=mod.Model(K,H).cuda().eval();x=torch.rand(B,K,device='cuda')
        ref=m(x);out=fast.forward(x,m.gemm.weight,m.gemm.bias,m.subtract)
        r={'shape':[B,K,H],**summarize(ref,out)}
        r['timing']=measure({'eager':lambda:m(x),'torch_factored':lambda:fast.torch_factored(x,m.gemm.weight,m.gemm.bias,m.subtract),'cuda_factored':lambda:fast.forward(x,m.gemm.weight,m.gemm.bias,m.subtract)},rounds=15)
        results['shape_transfer'].append(r);print(json.dumps(r),flush=True)
        del m,x,ref,out;gc.collect();torch.cuda.empty_cache()
    torch.manual_seed(42);m=mod.Model(*mod.get_init_inputs()).cuda().eval();x=mod.get_inputs()[0].cuda()
    # Replaying a graph must recompute from changed values, not replay a cached answer.
    stream=torch.cuda.Stream();stream.wait_stream(torch.cuda.current_stream())
    with torch.cuda.stream(stream):
        for _ in range(3):fast.forward(x,m.gemm.weight,m.gemm.bias,m.subtract)
    torch.cuda.current_stream().wait_stream(stream)
    graph=torch.cuda.CUDAGraph()
    with torch.cuda.graph(graph):out=fast.forward(x,m.gemm.weight,m.gemm.bias,m.subtract)
    m.gemm.weight.add_(.0001);x.mul_(.9);graph.replay()
    results['controls'].append({'name':'graph_replay_after_weight_and_input_mutation',**summarize(m(x),out)})
    stream=torch.cuda.Stream();stream.wait_stream(torch.cuda.current_stream())
    with torch.cuda.stream(stream):
        out_stream=fast.forward(x,m.gemm.weight,m.gemm.bias,m.subtract)
        ref_stream=m(x)
    torch.cuda.current_stream().wait_stream(stream)
    results['controls'].append({'name':'nondefault_stream',**summarize(ref_stream,out_stream)})
    # Construct cancellation: repeated input, with column zero exposing scalar error.
    # Subtract the actual eager linear output (not a mathematical oracle).
    row=torch.rand(1,x.shape[1],device='cuda');row[0,0]=0
    x.copy_(row.expand_as(x))
    m.gemm.weight.mul_(100000)
    m.subtract.copy_(m.gemm(x)[0])
    ref=m(x)
    for name,fn in [('torch_factored',fast.torch_factored),('cuda_factored',fast.forward)]:
        out=fn(x,m.gemm.weight,m.gemm.bias,m.subtract)
        results['controls'].append({'name':'constructed_cancellation_scale_1e5','method':name,
            'parameters':'seed42; weight plus 1e-4 then times 1e5; repeated uniform row with first column 0; subtract=reference_linear(x)[0]',**summarize(ref,out),
            'reference_first':ref[0,0].item(),'candidate_first':out[0,0].item()})
    # Explicitly record the unavailable compiler baseline, rather than claiming it ran.
    try:
        compiled=torch.compile(m)
        compiled(x)
        results['inductor']='available, but cancellation model is not a timing baseline'
    except Exception as exc:results['inductor_error']=str(exc)
    (ROOT/'controls51.json').write_text(json.dumps(results,indent=2))
    print(json.dumps(results['controls']),flush=True)
    print('inductor',results.get('inductor_error',results.get('inductor')),flush=True)

if __name__=='__main__':main()

```


